def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find background (most common color) and special cells
    # Assuming background is most frequent or first color that fills grid
    bg = grid[0][0]

    # Find source positions (special cells, likely in last column)
    sources = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                sources.append((r, grid[r][c]))

    # Initialize output grid with background
    output = [[bg for _ in range(cols)] for _ in range(rows)]

    # Apply transformations for each source
    for sr, v in sources:
        # Affected rows: sr-1, sr, sr+1 (within bounds)
        start_row = max(0, sr - 1)
        end_row = min(rows - 1, sr + 1)

        for r in range(start_row, end_row + 1):
            if r % 2 == sr % 2:  # Same parity as source row
                # Start with v at even column
                for c in range(cols):
                    if c % 2 == 0:
                        output[r][c] = v
                    else:
                        output[r][c] = bg
            else:  # Different parity
                # Start with bg at even column
                for c in range(cols):
                    if c % 2 == 0:
                        output[r][c] = bg
                    else:
                        output[r][c] = v

    return output
